export const getClosePaperTradeUrl = (id: string,) => {




  return `/api/journal/trades/${id}/paper-close`
}

/**
 * Requires an owner-entered simulated exit price. Never submits an exchange order or invents a market fill.
 * @summary Owner manually closes the remaining simulated paper position
 */
export const closePaperTrade = async (id: string,
    paperCloseRequest: PaperCloseRequest, options?: Parameters<typeof customFetch>[1]): Promise<JournalTrade> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<JournalTrade>(getClosePaperTradeUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(paperCloseRequest)
  }
);}





export const getClosePaperTradeMutationKey = () => ['closePaperTrade'] as const;

export const getClosePaperTradeMutationOptions = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof closePaperTrade>>, TError,ClosePaperTradeMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof closePaperTrade>>, TError,ClosePaperTradeMutationVariables, TContext> => {

const mutationKey = getClosePaperTradeMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof closePaperTrade>>, ClosePaperTradeMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  closePaperTrade(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ClosePaperTradeMutationResult = NonNullable<Awaited<ReturnType<typeof closePaperTrade>>>
    export type ClosePaperTradeMutationBody = BodyType<PaperCloseRequest>
    export type ClosePaperTradeMutationError = ErrorType<void>
    export type ClosePaperTradeMutationVariables = {id: string;data: BodyType<PaperCloseRequest>}

    /**
 * @summary Owner manually closes the remaining simulated paper position
 */
export const useClosePaperTrade = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof closePaperTrade>>, TError,ClosePaperTradeMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof closePaperTrade>>,
        TError,
        ClosePaperTradeMutationVariables,
        TContext
      > => {
      return useMutation(getClosePaperTradeMutationOptions(options));
    }

